import{_ as h,I as e,o,c,b6 as i,j as a,J as l,w as t,a as n}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"在線考試與管理系統開發實戰","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/assignments/exam-management-express/index.md","filePath":"zh-tw/stage-2/assignments/exam-management-express/index.md"}'),b={name:"zh-tw/stage-2/assignments/exam-management-express/index.md"},u={style:{margin:"32px 0"}};function k(g,s,m,x,f,_){const p=e("StepBar"),d=e("ClientOnly"),r=e("el-card");return o(),c("div",null,[s[2]||(s[2]=i('<h1 id="在線考試與管理系統開發實戰" tabindex="-1">在線考試與管理系統開發實戰 <a class="header-anchor" href="#在線考試與管理系統開發實戰" aria-label="Permalink to “在線考試與管理系統開發實戰”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本實戰項目要求你圍繞一份真實的 PRD，從零完成一個在線考試與管理系統。這個項目的特別之處在於它包含多個角色（學生和管理員），每個角色看到的頁面和能執行的操作不同。你將使用 Express 構建後端，實現完整的考試業務鏈路。</p><p>這是 Stage 2 的綜合實戰環節。多角色權限系統在實際工作中非常常見，掌握這種模式後，你能夠應對教培、SaaS、後臺管理等各類業務場景。</p><h2 id="前置知識" tabindex="-1">前置知識 <a class="header-anchor" href="#前置知識" aria-label="Permalink to “前置知識”">​</a></h2><p>在開始本項目之前，你應該已經掌握以下內容：</p><ul><li>前端頁面設計與組件庫使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">現代組件庫</a>）</li><li>後端接口設計與開發（<a href="./../../backend/ai-interface-code/">接口程式碼編寫</a>）</li><li>資料庫基礎與 Supabase（<a href="./../../backend/database-supabase/">從資料庫到 Supabase</a>）</li><li>Git 工作流與部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 應用</a>）</li></ul><h2 id="學習目標" tabindex="-1">學習目標 <a class="header-anchor" href="#學習目標" aria-label="Permalink to “學習目標”">​</a></h2><p>完成本實戰後，你將能夠：</p><ol><li>閱讀並理解一份真實的 PRD，從中提取開發任務清單</li><li>設計多角色系統的權限控制和頁面路由</li><li>使用 Express 實現完整的後端 API</li><li>實現考試、提交、自動判分的業務鏈路</li><li>完成端到端聯調，交付一個可演示的業務系統原型</li></ol><h2 id="項目簡介" tabindex="-1">項目簡介 <a class="header-anchor" href="#項目簡介" aria-label="Permalink to “項目簡介”">​</a></h2><p>你要構建的產品是一個在線考試與管理系統，包含三個子系統：</p><table tabindex="0"><thead><tr><th>子系統</th><th>職責</th></tr></thead><tbody><tr><td><strong>官網前臺</strong></td><td>平臺介紹、登錄入口</td></tr><tr><td><strong>學生端</strong></td><td>考試列表、答題、提交、成績查看</td></tr><tr><td><strong>管理後臺</strong></td><td>題庫管理、考試管理、提交記錄、成績統計</td></tr></tbody></table><p>後端使用 Express，需要支持：登錄鑑權、角色權限、考試和題庫管理、提交流程與自動判分、成績和統計管理。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本項目的需求文檔在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-tw/stage-2/assignments/exam-management-express/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',15)),a("div",u,[l(d,null,{default:t(()=>[l(p,{active:0,items:[{title:"需求分析",description:"閱讀 PRD，明確角色、頁面、考試鏈路和資料模型"},{title:"搭建骨架",description:"用 AI 生成學生端和管理端頁面骨架"},{title:"後端開發",description:"Express 接通登錄、考試、提交、判分"},{title:"聯調上線",description:"端到端跑通，部署並準備演示"}]})]),_:1})]),s[3]||(s[3]=i(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-閱讀-prd" tabindex="-1">1.1 閱讀 PRD <a class="header-anchor" href="#_1-1-閱讀-prd" aria-label="Permalink to “1.1 閱讀 PRD”">​</a></h3><p>打開 PRD 文檔，重點回答以下問題：</p><ul><li>系統包含哪幾個角色？各自能做什麼？</li><li>頁面清單是否完整？學生端和管理端分別有哪些頁面？</li><li>支持哪些題型？每種題型的判分邏輯是什麼？</li><li>考試的完整流程是什麼？（發佈 → 開始 → 作答 → 提交 → 判分 → 查看成績）</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上問題沒有明確答案，不要開始寫程式碼。需求理解不清楚是導致返工的最常見原因。</p></div><h3 id="_1-2-確認系統架構" tabindex="-1">1.2 確認系統架構 <a class="header-anchor" href="#_1-2-確認系統架構" aria-label="Permalink to “1.2 確認系統架構”">​</a></h3><p>根據 PRD 梳理出系統的整體架構：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;官網前臺&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; student[&quot;學生端&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;管理後臺&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; auth[&quot;鑑權&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  student --&gt; exam[&quot;考試與作答&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exam --&gt; db[&quot;資料庫&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; question[&quot;題庫管理&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; submission[&quot;提交記錄與成績統計&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  question --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  submission --&gt; db</span></span></code></pre></div><h2 id="第二部分-搭建項目骨架" tabindex="-1">第二部分：搭建項目骨架 <a class="header-anchor" href="#第二部分-搭建項目骨架" aria-label="Permalink to “第二部分：搭建項目骨架”">​</a></h2><h3 id="_2-1-生成前端頁面" tabindex="-1">2.1 生成前端頁面 <a class="header-anchor" href="#_2-1-生成前端頁面" aria-label="Permalink to “2.1 生成前端頁面”">​</a></h3><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請基於當前 PRD，幫我生成一個在線考試與管理系統的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>技術棧要求：</span></span>
<span class="line"><span>- Next.js App Router</span></span>
<span class="line"><span>- TypeScript</span></span>
<span class="line"><span>- Tailwind CSS</span></span>
<span class="line"><span>- shadcn/ui</span></span>
<span class="line"><span></span></span>
<span class="line"><span>頁面清單：</span></span>
<span class="line"><span>1. 首頁 /</span></span>
<span class="line"><span>2. 登錄頁 /login</span></span>
<span class="line"><span>3. 學生考試列表頁 /student/exams</span></span>
<span class="line"><span>4. 學生答題頁 /student/exams/[id]</span></span>
<span class="line"><span>5. 學生成績頁 /student/history</span></span>
<span class="line"><span>6. 管理後臺首頁 /admin</span></span>
<span class="line"><span>7. 考試管理頁 /admin/exams</span></span>
<span class="line"><span>8. 題庫管理頁 /admin/questions</span></span>
<span class="line"><span>9. 提交記錄頁 /admin/submissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 學生端頁面強調清晰、專注、易答題</span></span>
<span class="line"><span>- 管理端頁面使用側邊欄 + 頂部欄佈局</span></span>
<span class="line"><span>- 先使用 mock 資料，不接真實接口</span></span>
<span class="line"><span>- 注意桌面端和移動端的基本可用性</span></span></code></pre></div><h3 id="_2-2-完善學生答題頁" tabindex="-1">2.2 完善學生答題頁 <a class="header-anchor" href="#_2-2-完善學生答題頁" aria-label="Permalink to “2.2 完善學生答題頁”">​</a></h3><p>答題頁是學生端的核心頁面，重點完善：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請繼續完善學生答題頁。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>這是一個在線考試系統的答題頁面，需要包含：</span></span>
<span class="line"><span>- 頂部顯示考試標題、倒計時、已答題數量</span></span>
<span class="line"><span>- 中間顯示題乾和選項</span></span>
<span class="line"><span>- 支持單選、判斷、簡答三種題型</span></span>
<span class="line"><span>- 左側或頂部有答題卡，顯示每道題是否已作答</span></span>
<span class="line"><span>- 點擊提交前彈出確認框</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先用 mock 資料實現交互，不接真實接口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 界面簡潔，不要像後臺表格頁</span></span>
<span class="line"><span>- 倒計時要醒目，但不要製造過強壓迫感</span></span>
<span class="line"><span>- 有空狀態和 loading 狀態</span></span></code></pre></div><h3 id="_2-3-完善管理員後臺" tabindex="-1">2.3 完善管理員後臺 <a class="header-anchor" href="#_2-3-完善管理員後臺" aria-label="Permalink to “2.3 完善管理員後臺”">​</a></h3><p>管理員後臺第一版聚焦三個核心區域：</p><ul><li><strong>考試管理</strong>：創建考試、設置時長、發佈狀態</li><li><strong>題庫管理</strong>：新增題目、編輯題目、按題型篩選</li><li><strong>提交記錄</strong>：查看學生提交、分數、時間</li></ul><h3 id="_2-4-驗證頁面結構" tabindex="-1">2.4 驗證頁面結構 <a class="header-anchor" href="#_2-4-驗證頁面結構" aria-label="Permalink to “2.4 驗證頁面結構”">​</a></h3><p>逐項檢查：</p><ul><li>[ ] 學生端和管理端入口是否分開</li><li>[ ] 登錄頁、考試列表、答題頁、成績頁是否完整</li><li>[ ] 管理端題庫、考試管理、提交記錄頁是否可訪問</li><li>[ ] 學生端和管理端的頁面風格有明顯區分</li></ul><h3 id="遇到阻礙" tabindex="-1">遇到阻礙？ <a class="header-anchor" href="#遇到阻礙" aria-label="Permalink to “遇到阻礙？”">​</a></h3><p>如果你在前端搭建階段卡住，可以回顧這些章節：</p><ul><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">應用後端接口設計與開發</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li></ul><h2 id="第三部分-後端開發" tabindex="-1">第三部分：後端開發 <a class="header-anchor" href="#第三部分-後端開發" aria-label="Permalink to “第三部分：後端開發”">​</a></h2><h3 id="_3-1-登錄與權限控制" tabindex="-1">3.1 登錄與權限控制 <a class="header-anchor" href="#_3-1-登錄與權限控制" aria-label="Permalink to “3.1 登錄與權限控制”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請把我當成 0 基礎，幫我完成在線考試系統的登錄與權限控制。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>後端使用 Express。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目標：</span></span>
<span class="line"><span>1. 學生和管理員都可以登錄</span></span>
<span class="line"><span>2. 登錄後返回用戶角色</span></span>
<span class="line"><span>3. 學生只能訪問 /student/* 相關接口</span></span>
<span class="line"><span>4. 管理員只能訪問 /admin/* 相關接口</span></span>
<span class="line"><span>5. 未登錄用戶訪問受保護頁面時跳轉 /login</span></span>
<span class="line"><span></span></span>
<span class="line"><span>實現要求：</span></span>
<span class="line"><span>- 給出清晰的目錄結構建議</span></span>
<span class="line"><span>- 明確說明中間件負責什麼</span></span>
<span class="line"><span>- 涉及環境變量的地方不要硬編碼</span></span>
<span class="line"><span>- 完成後說明如何驗證權限是否生效</span></span></code></pre></div><h3 id="_3-2-考試與題庫管理接口" tabindex="-1">3.2 考試與題庫管理接口 <a class="header-anchor" href="#_3-2-考試與題庫管理接口" aria-label="Permalink to “3.2 考試與題庫管理接口”">​</a></h3><p>建議按以下模塊實現：</p><table tabindex="0"><thead><tr><th>模塊</th><th>推薦接口</th></tr></thead><tbody><tr><td>考試管理</td><td><code>GET /api/exams</code>、<code>POST /api/admin/exams</code>、<code>PATCH /api/admin/exams/:id</code></td></tr><tr><td>題庫管理</td><td><code>GET /api/admin/questions</code>、<code>POST /api/admin/questions</code></td></tr><tr><td>開始考試</td><td><code>POST /api/submissions/start</code></td></tr><tr><td>提交試卷</td><td><code>POST /api/submissions/:id/submit</code></td></tr><tr><td>成績記錄</td><td><code>GET /api/student/history</code>、<code>GET /api/admin/submissions</code></td></tr></tbody></table><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請幫我為在線考試系統設計並實現 Express API。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能範圍：</span></span>
<span class="line"><span>- 管理員創建考試</span></span>
<span class="line"><span>- 管理員維護題庫</span></span>
<span class="line"><span>- 學生查看已發佈考試</span></span>
<span class="line"><span>- 學生開始考試並創建 submission</span></span>
<span class="line"><span>- 學生提交答案後自動判分單選題和判斷題</span></span>
<span class="line"><span>- 簡答題先標記為待複核</span></span>
<span class="line"><span>- 學生查看自己的歷史成績</span></span>
<span class="line"><span>- 管理員查看所有提交記錄</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 接口命名清晰</span></span>
<span class="line"><span>- 返回統一 JSON 結構</span></span>
<span class="line"><span>- 程式碼中區分 controller、service、middleware、db 層</span></span>
<span class="line"><span>- 說明每個接口如何測試</span></span></code></pre></div><h3 id="_3-3-判分邏輯" tabindex="-1">3.3 判分邏輯 <a class="header-anchor" href="#_3-3-判分邏輯" aria-label="Permalink to “3.3 判分邏輯”">​</a></h3><p>判分邏輯是考試系統的核心業務規則：</p><ul><li><strong>單選題</strong>：用戶答案與標準答案一致則得分</li><li><strong>判斷題</strong>：同樣可以自動判分</li><li><strong>簡答題</strong>：第一版先只保存答案，分數為空，狀態為 <code>reviewed = false</code></li></ul><div class="tip custom-block"><p class="custom-block-title">加分項</p><p>如果你想增加 AI 能力，可以讓管理員在後臺輸入&quot;主題 + 難度&quot;，由模型先生成一批候選題，再人工審核後入庫。但這屬於加分項，不是必須的。</p></div><h2 id="第四部分-聯調與上線" tabindex="-1">第四部分：聯調與上線 <a class="header-anchor" href="#第四部分-聯調與上線" aria-label="Permalink to “第四部分：聯調與上線”">​</a></h2><h3 id="_4-1-端到端測試" tabindex="-1">4.1 端到端測試 <a class="header-anchor" href="#_4-1-端到端測試" aria-label="Permalink to “4.1 端到端測試”">​</a></h3><p>至少驗證以下場景：</p><ul><li>學生登錄 → 查看考試列表 → 開始答題 → 提交 → 查看成績</li><li>管理員登錄 → 創建考試 → 添加題目 → 發佈 → 查看提交記錄</li></ul><h3 id="_4-2-部署" tabindex="-1">4.2 部署 <a class="header-anchor" href="#_4-2-部署" aria-label="Permalink to “4.2 部署”">​</a></h3><ul><li>前端部署到 Vercel / Zeabur</li><li>Express API 部署到 Zeabur / Railway / Render</li><li>資料庫用 Supabase Postgres 或託管 PostgreSQL</li></ul><p>部署前檢查：</p><ul><li>[ ] 環境變量是否齊全</li><li>[ ] 前後端 API 地址是否正確</li><li>[ ] 登錄態在生產環境是否正常</li><li>[ ] 管理員賬號是否能真實訪問後臺</li><li>[ ] README 是否包含啟動、部署、測試說明</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本項目後，你需要提交以下內容：</p><ul><li>[ ] 可訪問的線上演示鏈接</li><li>[ ] 源碼倉庫鏈接（含 README）</li><li>[ ] PRD 文檔</li><li>[ ] 核心頁面截圖（首頁、學生考試列表、答題頁、管理後臺）</li><li>[ ] 60 秒演示影片（覆蓋學生答題流程和管理員管理流程）</li></ul><p>README 至少包含：項目簡介、核心頁面說明、技術棧、本地啟動步驟、環境變量清單。</p><h2 id="評分標準" tabindex="-1">評分標準 <a class="header-anchor" href="#評分標準" aria-label="Permalink to “評分標準”">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>基本要求</th><th>進階要求</th></tr></thead><tbody><tr><td>頁面完整度</td><td>學生端和管理端主要頁面都可訪問</td><td>頁面風格統一，移動端基本可用</td></tr><tr><td>業務閉環</td><td>學生可登錄、參加考試、提交併查看成績</td><td>管理員可完整創建併發布考試</td></tr><tr><td>資料正確性</td><td>提交答案後能寫入資料庫，客觀題能自動判分</td><td>簡答題支持人工複核或 AI 輔助</td></tr><tr><td>權限控制</td><td>學生與管理員訪問邊界清晰</td><td>服務端接口也有角色校驗</td></tr><tr><td>工程交付</td><td>項目可運行、可部署、README 清晰</td><td>有演示影片和測試說明</td></tr></tbody></table><h2 id="提交前檢查" tabindex="-1">提交前檢查 <a class="header-anchor" href="#提交前檢查" aria-label="Permalink to “提交前檢查”">​</a></h2>`,51)),l(r,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:t(()=>[...s[0]||(s[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"提交前最後看一眼",-1)])]),default:t(()=>[s[1]||(s[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 首頁、登錄頁、學生端、管理端頁面均已完成")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 學生可以正常開始考試並提交答案")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 管理員可以創建考試並查看提交記錄")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 客觀題分數能夠自動計算並寫入資料庫")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 學生與管理員權限邊界已驗證")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" 項目已部署或具備完整本地運行說明")])])],-1))]),_:1}),s[4]||(s[4]=i('<h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型輔助編寫接口程式碼與接口文檔</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a></li></ul>',2))])}const y=h(b,[["render",k]]);export{P as __pageData,y as default};
